coding.solution:
import re

def java_major(version_output):
    m = re.search(r'"([^"]+)"', version_output)
    if not m:
        return None
    parts = re.split(r'[._+-]', m.group(1))
    if parts[0] == '1' and len(parts) > 1:
        return int(parts[1])
    return int(parts[0])

