def preflight(java_major, jmeter_version, folder):
    problems = []
    major = int(jmeter_version.split('.')[0])
    needed = 8 if major <= 5 else 17
    if java_major is None or java_major < needed:
        problems.append('java too old')
    if '_src' in folder:
        problems.append('source download')
    if ' ' in folder:
        problems.append('space in path')
    return problems
